    /**
     * Handles create a Opportunity.  if not key provided, calls create, otherwise calls save
     * @param		Opportunity	opportunity
     * @return		Opportunity 
     */
	@PostMapping("/create")
    public Opportunity create( @RequestBody(required=true) CreateOpportunityCommand command ) {
    	Opportunity entity = null;

		entity = service.createOpportunity( command );
		LOGGER.info( "Successfully created Opportunity with Id " + entity.getOpportunityId()  );

		return entity;
    }

    /**
     * Handles updating a Opportunity.  if no key provided, calls create, otherwise calls save
     * @param		Opportunity opportunity
     * @return		Opportunity
     */
	@PutMapping("/update")
    public Opportunity update( @RequestBody(required=true) UpdateOpportunityCommand command ) {
		Opportunity entity = null;

		entity = service.updateOpportunity(command);
		LOGGER.info( "Successfully updated Opportunity with Id " + command.getOpportunityId()  );

		return entity;
	}
 
    /**
     * Handles deleting a Opportunity entity
     * @param		command ${class.getDeleteCommandAlias()}
     */
    @DeleteMapping("/delete")    
    public void delete( @RequestBody(required=true) DeleteOpportunityCommand command ) {                
		service.delete( command );
		LOGGER.info( "Successfully deleted Opportunity with Id " + command.getOpportunityId()  );
	}
	
    /**
     * Handles loading a Opportunity using a UUID
     * @param		UUID uuid 
     * @return		Opportunity
     */    
    @GetMapping("/load")
    public Opportunity load( @RequestParam(required=true) UUID uuid ) {
    	Opportunity entity = service.getOpportunity( new OpportunityFetchOneSummary( uuid ) );

		LOGGER.info( "Successfully loaded Opportunity with Id " + uuid   );

        return entity;
    }

    /**
     * Handles loading all Opportunity business objects
     * @return		Set<Opportunity>
     */
    @GetMapping("/")
    public List<Opportunity> loadAll() {                
    	List<Opportunity> opportunityList = null;

		opportunityList = service.getAllOpportunity();
		LOGGER.info( "successfully loaded all Opportunitys" );

        return opportunityList;
                            
    }

